'use strict';
const KEY='ielts-four-month-plan-v1';
const DEFAULT_START='2026-10-08';
const PLAN_DATE_REVISION=1;
const LEGACY_DEFAULT_STARTS=['2026-10-04','2026-10-05'];
const $=s=>document.querySelector(s);
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today=()=>iso(new Date());
const parseDate=s=>new Date(s+'T12:00:00Z');
const dateOK=s=>typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&!isNaN(parseDate(s))&&parseDate(s).toISOString().slice(0,10)===s;
const plusDays=(s,n)=>{const d=parseDate(s);d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};
function plusMonths(s,n){const d=parseDate(s),day=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+n);const last=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();d.setUTCDate(Math.min(day,last));return d.toISOString().slice(0,10)}
const dayDiff=(a,b)=>Math.round((parseDate(b)-parseDate(a))/86400000);
const dateLabel=s=>s.slice(5).replace('-',' / ');
const overall=vals=>Math.round((vals.reduce((a,b)=>a+Number(b),0)/4)*2)/2;
const bandOK=v=>typeof v==='number'&&Number.isFinite(v)&&v>=0&&v<=9&&Number.isInteger(v*2);
const blankOrBand=v=>v===''||v===null||bandOK(v);
const makeDefault=()=>({version:1,planDateRevision:PLAN_DATE_REVISION,settings:{start:DEFAULT_START,goal:8,mode:'normal',targets:[8.5,8.5,7.5,7.5],examMode:'unknown'},checks:{},notes:{},diagnostic:{L:'',R:'',W:'',S:'',Lraw:'',Rraw:'',feedback:'pending'},scores:[],fragments:[],diagnosticChecks:{},dayChecks:{},dailyNotes:{},learning:{seen:3180,total:3527,newLimit:20,phase:'firstpass',entries:[]}});
function sanitize(input){
 if(!input||typeof input!=='object'||Array.isArray(input)||input.version!==1)throw Error('不支持的备份版本。请导入此网站导出的JSON。');
 const s=input.settings;if(!s||!dateOK(s.start)||!['normal','busy','stretch'].includes(s.mode)||![8,8.5].includes(s.goal)||!Array.isArray(s.targets)||s.targets.length!==4||!s.targets.every(bandOK)||!['computer','paper','unknown'].includes(s.examMode))throw Error('计划设置格式无效。');
 const out=makeDefault();out.settings={start:s.start,goal:s.goal,mode:s.mode,targets:s.targets.slice(),examMode:s.examMode};
 // Apply this requested date change once to legacy defaults, including old backups.
 // Keep task IDs and every record on its original training-day index. Later custom dates win.
 const revision=Number.isInteger(input.planDateRevision)&&input.planDateRevision>=0?input.planDateRevision:0;
 if(revision<PLAN_DATE_REVISION&&LEGACY_DEFAULT_STARTS.includes(s.start))out.settings.start=DEFAULT_START;
 out.planDateRevision=Math.max(revision,PLAN_DATE_REVISION);
 for(const name of ['checks','diagnosticChecks']){if(input[name]&&typeof input[name]==='object'&&!Array.isArray(input[name]))Object.entries(input[name]).slice(0,10000).forEach(([k,v])=>{if(/^[A-Za-z0-9_-]{1,90}$/.test(k)&&typeof v==='boolean')out[name][k]=v})}
 if(input.notes&&typeof input.notes==='object'&&!Array.isArray(input.notes))Object.entries(input.notes).slice(0,100).forEach(([k,v])=>{if(/^w\d{1,2}$/.test(k)&&typeof v==='string')out.notes[k]=v.slice(0,5000)});
 if(input.diagnostic){const d=input.diagnostic;['L','R','W','S'].forEach(k=>{if(!blankOrBand(d[k]))throw Error('诊断分数必须是0–9的半分档。');out.diagnostic[k]=d[k]??''});['Lraw','Rraw'].forEach(k=>{if(d[k]!==''&&d[k]!==null&&(!Number.isInteger(d[k])||d[k]<0||d[k]>40))throw Error('原始分必须是0–40的整数。');out.diagnostic[k]=d[k]??''});if(['pending','self','ai','qualified'].includes(d.feedback))out.diagnostic.feedback=d.feedback}
 if(!Array.isArray(input.scores)||input.scores.length>500)throw Error('成绩记录格式无效或超过500条。');out.scores=input.scores.map((r,i)=>{if(!r||!dateOK(r.date)||!Array.isArray(r.bands)||r.bands.length!==4||!r.bands.every(bandOK)||!['new','repeat','official'].includes(r.type)||!['qualified','self','ai','pending'].includes(r.feedback))throw Error('第'+(i+1)+'条成绩记录无效。');return{id:String(r.id??('score_'+i)).replace(/[^a-zA-Z0-9_-]/g,'').slice(0,80)||('score_'+i),date:r.date,bands:r.bands.slice(),type:r.type,feedback:r.feedback,notes:String(r.notes??'').slice(0,1000)}});
 if(input.dayChecks&&typeof input.dayChecks==='object'&&!Array.isArray(input.dayChecks))Object.entries(input.dayChecks).slice(0,10000).forEach(([k,v])=>{if(/^[A-Za-z0-9_-]{1,100}$/.test(k)&&typeof v==='boolean')out.dayChecks[k]=v});
 if(input.dailyNotes&&typeof input.dailyNotes==='object'&&!Array.isArray(input.dailyNotes))Object.entries(input.dailyNotes).slice(0,10000).forEach(([k,v])=>{if(/^[A-Za-z0-9_-]{1,100}$/.test(k)&&typeof v==='string')out.dailyNotes[k]=v.slice(0,2000)});
 if(input.learning){const l=input.learning;if(!Number.isInteger(l.seen)||l.seen<0||l.seen>3527||!Number.isInteger(l.newLimit)||l.newLimit<1||l.newLimit>50||!['firstpass','review'].includes(l.phase))throw Error('词汇进度设置无效。');out.learning={seen:l.seen,total:3527,newLimit:l.newLimit,phase:l.phase,entries:[]};if(l.entries){if(!Array.isArray(l.entries)||l.entries.length>500)throw Error('错词记录格式无效或超过500条。');out.learning.entries=l.entries.map((x,i)=>{if(!x||!dateOK(x.due)||typeof x.term!=='string'||!x.term.trim()||!Number.isInteger(x.streak)||x.streak<0||x.streak>100)throw Error('错词记录格式无效。');return{id:String(x.id||('word_'+i)).replace(/[^a-zA-Z0-9_-]/g,'').slice(0,80)||('word_'+i),term:x.term.slice(0,120),meaning:String(x.meaning||'').slice(0,600),example:String(x.example||'').slice(0,1000),due:x.due,streak:x.streak,last:['forgot','hard','easy','new'].includes(x.last)?x.last:'new'}})}}
 if(new Set(out.scores.map(x=>x.id)).size!==out.scores.length)throw Error('成绩记录ID重复，请检查备份。');if(new Set(out.learning.entries.map(x=>x.id)).size!==out.learning.entries.length)throw Error('错词记录ID重复，请检查备份。');
 if(Array.isArray(input.fragments))out.fragments=input.fragments.slice(-1000).filter(x=>x&&dateOK(x.date)&&[5,10,20,45,90].includes(x.minutes)).map(x=>({date:x.date,minutes:x.minutes}));return out;
}
let storageWorks=true,state,recoveryRaw=null,loadedRaw=null,dateMigrationPending=false;
try{loadedRaw=localStorage.getItem(KEY);const loaded=loadedRaw?JSON.parse(loadedRaw):null;state=loaded?sanitize(loaded):makeDefault();dateMigrationPending=!!loaded&&loaded.planDateRevision!==state.planDateRevision}catch(e){state=makeDefault();storageWorks=false;recoveryRaw=loadedRaw;setTimeout(()=>toast('已有数据未能读取。已暂停覆盖保存；导出可取回原始数据，再重置或导入。'),300)}
let currentPage=location.hash.slice(1)||'today',selectedWeek=1,method='L',focusMinutes=10,timerLeft=600,timerEnd=null,timerInterval=null,pendingConfirm=null,toastTimeout;
const nav=[['today','今日任务','M3 10l9-7 9 7v10H3z M9 20v-7h6v7','01'],['roadmap','四个月路线','M5 3v18 M5 5h14l-3 4 3 4H5','02'],['methods','四科训练','M4 4h6c2 0 2 2 2 2s0-2 2-2h6v15h-6c-2 0-2 2-2 2s0-2-2-2H4z M12 6v15','03'],['diagnostic','起点诊断','M4 20V10h4v10 M10 20V4h4v16 M16 20v-8h4v8','04'],['scores','成绩与复盘','M3 17l6-6 4 3 8-10 M16 4h5v5 M3 21h18','05'],['vocab','词汇与纸书','M4 4h7v16H4z M13 4h7v16h-7 M7 8h1 M16 8h1','06'],['evidence','资料与依据','M5 3h10l4 4v14H5z M14 3v5h5 M8 12h8 M8 16h8','07']];
function save(){if(recoveryRaw!==null){storageWorks=false;$('#save-status').textContent='原数据异常：已暂停写入，请先导出原始备份';toast('为保护原数据，尚未保存修改。先导出原始备份，再确认重置或导入。');return false}try{localStorage.setItem(KEY,JSON.stringify(state));storageWorks=true;$('#save-status').textContent='已保存到本机 · '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});return true}catch(e){storageWorks=false;$('#save-status').textContent='本机保存失败，请立即导出JSON备份';toast('浏览器无法保存。请在设置中导出JSON，避免丢失进度。');return false}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),3800)}
function askConfirm(title,copy,fn){pendingConfirm=fn;$('#confirm-title').textContent=title;$('#confirm-copy').textContent=copy;$('#confirm-dialog').returnValue='';$('#confirm-dialog').showModal()}
$('#task-dialog').addEventListener('close',()=>{openTaskId=null});
$('#confirm-dialog').addEventListener('close',()=>{const f=pendingConfirm;pendingConfirm=null;if($('#confirm-dialog').returnValue==='confirm'&&f)f()});
function currentWeek(){return Math.max(1,Math.min(totalWeeks(),Math.floor(dayDiff(state.settings.start,today())/7)+1))}
function deadline(){return plusMonths(state.settings.start,4)}
function totalWeeks(){return Math.ceil(dayDiff(state.settings.start,deadline())/7)}
function weekInfo(w){return PLAN.weeks[w-1]||{title:'机动与考前窗口',L:'少量保持手感与错题回忆',R:'少量新题，不新开完整课程',W:'查看个人错误清单，保持简短输出',S:'自然交流与短练习，保障状态',deliver:['处理延误任务，保留恢复与休息','按可靠模拟证据确认考期','核对考点、证件与官方最新要求'],gate:'这是考前机动区，不用于无限补课。缓冲长度随月份变化；考试日期是规划日期，不是已预约。'}}
function taskDefs(w,mode=state.settings.mode){
 const info=weekInfo(w),b=PLAN.legacyBudgets[mode],list=[];
 const add=(cat,n,min,titles,desc)=>{for(let i=0;i<n;i++)list.push({id:`w${w}_${mode}_${cat}${i}`,cat,min,title:titles[i%titles.length],desc:typeof desc==='function'?desc(i):desc})};
 if(w===1){PLAN.diagnosticDays.forEach((d,i)=>list.push({id:`w1_diagnostic_D${i}`,cat:['L','R','W','R','W','S','F'][i],min:d[2],title:d[0]+' · '+d[1],desc:d[3]}));return list}
 const Ltitles=['听力限时与错因标注','弱题型精听与延迟复测'];const Rtitles=['阅读限时与用时记录','阅读证据与改写复盘'];
 add('L',b.parts[0]/60,60,Ltitles,info.L);add('R',b.parts[1]/60,60,Rtitles,info.R);
 add('W',b.parts[2]/60,60,mode==='busy'?['Task2限时40 + 反馈20','Task1限时20 + 修订40']:['Task2限时40 + 反馈10 + 列纲10','Task2限时40 + Task1限时20','反馈20 + 针对性重写40','最弱写作维度加练'],i=>info.W+(mode==='busy'?'；忙周两块中保留大小作文各一篇和修订。':''));
 add('S',b.parts[3]/30,30,['口语录音、回听、重答','Part2关键词与陌生追问','完整口试与标准反馈'],i=>info.S+(i===2?'；外部反馈不可用时标记待评。':''));
 if(b.parts[4])add('V',6,5,['错词回忆 · 先旧后新'], '用1/3/7天回忆复习，不额外添加每日词汇时长。');
 add('F',1,b.parts[5],['周复盘与下周排程'], '比较新题证据；保留两个优先问题，把工作和作品集时间先排入日历。');return list;
}
function weekStats(w){const list=taskDefs(w),done=list.filter(t=>state.checks[t.id]);return{list,total:list.reduce((a,t)=>a+t.min,0),done:done.length,minutes:done.reduce((a,t)=>a+t.min,0),pct:Math.round(done.reduce((a,t)=>a+t.min,0)/list.reduce((a,t)=>a+t.min,0)*100)}}
const fmtMin=n=>n>=60?(n/60).toFixed(n%60?1:0)+'小时':n+'分钟';
const badge=(s,cls='')=>`<span class="badge ${cls}">${s}</span>`;
const pageTitle=(eye,title,copy,extra='')=>`<div class="page-title"><div><span class="eyebrow">${eye}</span><h1>${title}</h1><p>${copy}</p></div>${extra}</div>`;
const modeSwitch=()=>`<div class="mode-switch" aria-label="周时间预算">${Object.entries(PLAN.budgets).map(([k,v])=>`<button data-mode="${k}" class="${state.settings.mode===k?'active':''}" aria-pressed="${state.settings.mode===k}">${v.label} ${v.tag}</button>`).join('')}</div>`;
function taskHTML(t){const checked=!!state.checks[t.id];return `<label class="task-row ${checked?'checked':''}"><input type="checkbox" data-task="${t.id}" ${checked?'checked':''} aria-label="完成 ${escapeHTML(t.title)}"><div class="task-content"><div class="task-name">${escapeHTML(t.title)}</div><div class="task-desc">${escapeHTML(t.desc)}</div><div class="task-meta"><span class="pill">${PLAN.categories.find(x=>x.key===t.cat)?.name||t.cat}</span><span>完成后勾选，进度自动保存</span></div></div><span class="task-min">${t.min} min</span></label>`}
function budgetHTML(){const b=PLAN.budgets[state.settings.mode];return`<div class="budget-bar">${b.parts.map((v,i)=>`<span style="width:${v/b.minutes*100}%;background:${PLAN.categories[i].color}"></span>`).join('')}</div><div class="budget-legend">${b.parts.map((v,i)=>`<span><i style="background:${PLAN.categories[i].color}"></i>${PLAN.categories[i].name} ${v}分钟</span>`).join('')}</div>`}
function focusHTML(){const f=PLAN.fragments[focusMinutes];return`<div class="panel-title"><div><h2>现在有一小段时间？</h2><p>选一个时间块，直接开始。</p></div>${badge('碎片训练')}</div><div class="time-tabs">${[5,10,20,45,90].map(n=>`<button data-focus="${n}" class="${focusMinutes===n?'active':''}" aria-pressed="${focusMinutes===n}">${n}分</button>`).join('')}</div><span class="eyebrow">${f.skill}</span><h3 class="focus-title">${f.title}</h3><ol class="focus-steps">${f.steps.map(s=>`<li>${s}</li>`).join('')}</ol><p class="inline-note">${f.output}</p><div class="focus-footer"><span class="timer" id="timer-text">${timerText()}</span><div class="timer-controls"><button data-action="timer-toggle">${timerEnd?'暂停':'开始计时'}</button><button class="secondary" data-action="timer-reset">重置计时</button><button class="soft" data-action="fragment-done">记一次练习</button></div></div><p class="inline-note">计时不会自动勾选周任务，也不额外累计周完成时长；用它拆分或替换已排任务。</p>`}
function timerText(){const n=timerEnd?Math.max(0,Math.ceil((timerEnd-Date.now())/1000)):timerLeft;return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
function startStopTimer(){if(timerEnd){timerLeft=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));timerEnd=null;clearInterval(timerInterval)}else{if(timerLeft<=0)timerLeft=focusMinutes*60;timerEnd=Date.now()+timerLeft*1000;timerInterval=setInterval(()=>{const el=$('#timer-text');if(el)el.textContent=timerText();if(Date.now()>=timerEnd){timerEnd=null;timerLeft=0;clearInterval(timerInterval);toast('时间到。留下一个练习结果，再决定是否继续。');if(currentPage==='today')render()}},300)}render()}
function todayHTML(){const w=currentWeek(),inf=weekInfo(w),st=weekStats(w),days=dayDiff(today(),deadline()),pending=st.list.filter(t=>!state.checks[t.id]).slice(0,4),phase=PLAN.phases[Math.min(3,Math.floor((w-1)/4))];return`${pageTitle('YOUR DAILY DESK','今天，向 8+ 走一步。','先做一件有反馈的事。四级620、六级568是基础；雅思起点由四科诊断决定。',badge('Academic · 已确认'))}<div class="hero-grid"><section class="mission"><div><span class="eyebrow">WEEK ${String(w).padStart(2,'0')} / ${String(totalWeeks()).padStart(2,'0')}</span><h2>${inf.title}</h2><p>${w===1?'这周先得到真实基线，口语与写作从第一天进入计划。':phase.focus}</p></div><div class="mission-number">${state.settings.goal}<sup>+</sup></div><div class="mission-bottom"><span>${dateLabel(state.settings.start)} 至 ${dateLabel(deadline())} · 4个自然月</span><span>${days>=0?'距规划考试日 '+days+' 天':'规划考试日已过 '+(-days)+' 天'}</span></div></section><section class="panel"><div class="summary-top"><div><span class="eyebrow">THIS WEEK</span><div class="stat-big">${(st.minutes/60).toFixed(1)} <small>/ ${(st.total/60).toFixed(1)} 小时</small></div></div>${badge(st.pct+'%','neutral')}</div><div class="progress" role="progressbar" aria-valuenow="${st.pct}" aria-valuemin="0" aria-valuemax="100" aria-label="本周完成进度"><span style="width:${st.pct}%"></span></div><div class="summary-facts"><span><b>${st.done} / ${st.list.length}</b>任务已完成</span><span><b>${w===1?'诊断周':PLAN.budgets[state.settings.mode].label}</b>总量可控</span><span><b>${state.fragments.filter(f=>f.date===today()).length} 次</b>今日碎片练习</span></div><button class="text-button" data-go="roadmap">查看本周完整清单</button></section></div><div class="main-grid"><section class="panel"><div class="panel-title"><div><h2>下一件该做的事</h2><p>W${String(w).padStart(2,'0')} · ${w===1?'诊断任务按日推进':'优先完成尚未完成的训练块'}</p></div>${badge(pending.length?'待执行':'本周完成','green')}</div>${pending.length?pending.map(taskHTML).join(''):'<div class="empty"><b>这周的清单已完成。</b>留出休息，再用新题与反馈判断下一步。</div>'}<button class="text-button" data-go="roadmap">打开全部任务与本周复盘</button><div class="hint">${inf.gate}</div></section><div class="stack"><section class="panel" id="focus-panel">${focusHTML()}</section></div></div><div class="section-heading"><h2>目标分配，把 8 拆成四科</h2><p>可在设置中修改；以下是目标，不是已测成绩。</p></div><div class="skill-strip">${['L','R','W','S'].map((k,i)=>`<article class="skill-card"><span class="letter">${k} / ${PLAN.categories[i].name}</span><div class="skill-value">${state.settings.targets[i].toFixed(1)} <small>目标</small></div><p>${state.diagnostic[k]===''?'起点待诊断':'诊断记录 '+Number(state.diagnostic[k]).toFixed(1)}</p></article>`).join('')}</div><p class="section-note">目标组合总分 ${overall(state.settings.targets).toFixed(1)}。总分8.0允许单科低于8；若学校另有小分要求，请把它加入目标。计划不承诺4个月必达8。</p>`}
function calendarHTML(w){const start=plusDays(state.settings.start,(w-1)*7);return `<div class="mini-calendar">${['一','二','三','四','五','六','日'].map(x=>`<small>周${x}</small>`).join('')}${Array.from({length:7},(_,i)=>{const weekMonday=plusDays(start,-((parseDate(start).getUTCDay()+6)%7)),d=plusDays(weekMonday,i);return`<span class="${d===today()?'today':''}">${dateLabel(d)}</span>`}).join('')}</div>`}
function roadmapHTML(){const w=selectedWeek,inf=weekInfo(w),st=weekStats(w),start=plusDays(state.settings.start,(w-1)*7),end=plusDays(start,6),span=dayDiff(state.settings.start,deadline()),phase=Math.min(3,Math.floor((w-1)/4));return`${pageTitle('THE FOUR-MONTH ROADMAP','16周训练 + 考前机动','四个月按自然月计算，不等于16周。先排作品集与课程，再选本周能完成的训练量。16个标准周共168小时，考前机动按状态减量。',modeSwitch())}<div class="calendar-strip"><span>开始 <b>${state.settings.start}</b></span><span>规划考试日 <b>${deadline()}</b></span><span>相隔 <b>${span}天 / ${(span/7).toFixed(1)}周</b></span><span>考前机动 <b>${span-112}天</b></span></div><p class="inline-note">规划日期可在设置中改变；并非已预约考试。含考试当天的末段日历窗口为${span-111}天。</p><div class="phase-grid" style="margin-top:22px">${PLAN.phases.map((p,i)=>`<div class="phase ${i===phase?'current':''}"><small>${p.weeks}</small><h3>${p.name}</h3><p>${p.focus}</p></div>`).join('')}</div><div class="week-tabs" aria-label="选择训练周">${Array.from({length:totalWeeks()},(_,i)=>`<button data-week="${i+1}" class="${w===i+1?'active':''} ${weekStats(i+1).pct===100?'completed':''}" aria-pressed="${w===i+1}">W${String(i+1).padStart(2,'0')}${i>=16?' 机动':''}</button>`).join('')}</div><div class="week-details"><section class="panel"><div class="panel-title"><div><span class="eyebrow">${start} — ${end<deadline()?end:deadline()}</span><h2>${inf.title}</h2></div>${badge(`${st.done}/${st.list.length}`)}</div><div class="progress" aria-label="所选周完成比例"><span style="width:${st.pct}%"></span></div>${w===1?'<div class="hint">首周采用独立630分钟诊断日程。预算按钮从第2周起应用；若首周很忙，可分两周完成诊断，但不要省掉口写反馈。</div>':''}${w>16?'<div class="hint warning">机动周清单是可选模板，不是必须全部完成。第18周不足7天，按实际剩余日期减量；考试前一天以轻复习和休息为主。</div>':''}${[4,8,12,14,16].includes(w)?'<div class="hint">本周完整模拟：连续预留约3小时完成听读写，口语另排。将左侧各科第一块集中到同一天，模拟替换原练习；从其他日腾出时间，总量保持不变，不把完整测试拆碎。</div>':''}<div style="margin-top:21px">${st.list.map(taskHTML).join('')}</div><div class="hint">合计 ${st.total} 分钟（${(st.total/60).toFixed(1)}小时），已包含词汇、录音和复盘。${state.settings.mode==='busy'?'忙周是临时保底，不具有与标准周相同的冲8预期；连续两周保底后重新评估时间或考期。':''}${state.settings.mode==='stretch'?'加量只补最弱输出项，不额外增加材料。':''}</div></section><div class="stack"><section class="panel"><h2>这周留下什么</h2><ul class="outputs">${inf.deliver.map(s=>`<li>${s}</li>`).join('')}</ul><div class="callout"><h3>本周检查点</h3><p>${inf.gate}</p></div></section><section class="panel"><h2>四科训练重心</h2>${['L','R','W','S'].map((k,i)=>`<div class="metric-line"><b>${PLAN.categories[i].name}</b><span>${inf[k]}</span></div>`).join('')}</section><section class="panel"><h2>本周时间账</h2>${w===1?'<p class="inline-note">诊断周按左侧7天合计630分钟；允许在同一周交换日期。</p>':budgetHTML()}<details><summary>标准周每日排法 · 630分钟</summary><div class="detail-body"><p>周一90：听力60 + 口语25 + 词汇5</p><p>周二105：阅读60 + 写作15 + 口语25 + 词汇5</p><p>周三90：Task2写作60 + 口语25 + 词汇5</p><p>周四105：听力60 + 写作15 + 口语25 + 词汇5</p><p>周五90：阅读60 + 口语25 + 词汇5</p><p>周六150：写作90 + 口语25 + 词汇5 + 周复盘30</p><p>周日0：免备考，休息。六次25分钟口语与清单五次30分钟是同一150分钟的两种切法，不重复完成。</p></div></details></section><section class="panel"><h2>周复盘</h2><label class="field" style="margin-top:12px">两个优先问题 + 下周如何调整<textarea id="week-note" maxlength="5000" placeholder="例：听力仍因复数失分；写作论点太泛。下周少做一篇额外阅读，给写作反馈30分钟。">${escapeHTML(state.notes['w'+w]||'')}</textarea></label><button class="soft" data-action="save-week-note">保存这周复盘</button><p class="inline-note">建议写证据：题号、评分维度、下一次如何验证。</p></section></div></div><div class="section-heading"><h2>每月决策，不盲目加码</h2></div><div class="three-col">${[['W04','基线与早期风险','若L/R仍明显低于7或W/S低于6.5，先补语言基础，再评估4个月目标。'],['W08','把时间投到弱项','若W/S仍在6–6.5，优先增加可靠反馈，把强项30–60分钟挪过来。'],['W12—15','看稳定证据定考期','听读看最近三次未见限时题；口写看标准反馈。以最弱项和波动决定是否延后。']].map(x=>`<section class="panel"><span class="eyebrow">${x[0]}</span><h3>${x[1]}</h3><p class="inline-note">${x[2]}</p></section>`).join('')}</div><p class="section-note">以上检查阈值是本计划的决策工具，不是官方通过线，也不预测成功概率。</p>`}
function methodsHTML(){const m=PLAN.methods[method];return`${pageTitle('TRAINING PLAYBOOK','每一次练习，都要有回路。','只保留少量可靠材料：做题 → 定位问题 → 修正 → 延迟重测 → 用新题验证。')}<div class="method-tabs">${Object.entries(PLAN.methods).map(([k,v])=>`<button data-method="${k}" class="${method===k?'active':''}" aria-pressed="${method===k}">${v.name}</button>`).join('')}</div><div class="method-lead"><span class="eyebrow">${m.english}</span><h2>${m.name} · ${m.target==='每日少量'?'少量高价值修复':'目标参考 '+m.target}</h2><p>${m.intro}</p></div>${methodResourceBlock(method)}<div class="two-col"><section class="panel"><div class="panel-title"><h2>具体怎么练</h2>${badge('可重复闭环')}</div><div class="numbered">${m.steps.map(([title,copy])=>`<div class="step"><div><h3>${title}</h3><p>${copy}</p></div></div>`).join('')}</div></section><div class="stack"><section class="panel"><h2>标准周的用法</h2><p style="margin-top:12px;font-size:.9375rem">${m.block}</p><div class="hint warning">${m.avoid}</div></section><section class="panel"><h2>练后自检</h2><div class="checklist">${m.check.map((x,i)=>`<label><input type="checkbox" data-method-check="${method}_${i}" ${state.diagnosticChecks['method_'+method+'_'+i]?'checked':''}><span>${x}</span></label>`).join('')}</div><p class="inline-note">勾选用于这次训练自检，不会自动获得分数。</p></section></div></div><div class="section-heading"><h2>少量资源，明确分工</h2></div><div class="two-col"><section class="panel"><div class="resource"><span class="resource-no">01</span><div><b>官方样题 / 正版剑桥材料</b><p>用于诊断、练习与阶段测量。把至少4套未见卷留给后期，题量服从复盘质量。</p><a href="https://ielts.org/take-a-test/preparation-resources/sample-test-questions" target="_blank" rel="noopener noreferrer">查看官方样题</a></div></div><div class="resource"><span class="resource-no">02</span><div><b>熟悉评分标准的反馈者</b><p>用于W/S诊断与阶段复核。优先能解释维度、举出原句证据并提出改法的人。人选和费用尚未选择。</p></div></div><div class="resource"><span class="resource-no">03</span><div><b>一个错词工具 + 手机录音</b><p>词汇只收真实失分点；录音保留前后两版。参考网页可辅助拼写，本站不复制其完整词库。</p><a href="https://hefengxian.com/my-ielts/#/" target="_blank" rel="noopener noreferrer">打开参考 MY IELTS</a></div></div></section><section class="panel"><h2>让反馈更可靠</h2><div class="callout"><h3>向反馈者提出这三个问题</h3><p>哪一项评分标准最限制我？请用我作品中的两处证据说明。下次练习只改变哪两个动作？</p></div><div class="callout"><h3>AI合适的辅助范围</h3><p>找可能的语法/逻辑问题、提出反问、模拟追问、比较修改前后表达。它可能误判，不能当作官方评分，也不能替代真实口语互动。</p></div><div class="callout"><h3>资料冲突时怎么选</h3><p>先看题还是先略读不设唯一答案。固定一种做法，用未见题的准确率、时间和失误类型比较，别每周换套路。</p></div></section></div>`}
function bandOptions(v,blank=true){return (blank?'<option value="">待测 / 待评</option>':'')+Array.from({length:19},(_,i)=>i/2).map(n=>`<option value="${n}" ${v!==''&&Number(v)===n?'selected':''}>${n.toFixed(1)}</option>`).join('')}
function diagnosticInterpretation(){const d=state.diagnostic,missing=['L','R','W','S'].filter(k=>d[k]==='');if(missing.length)return{title:'先填真实起点，再选训练路线',text:`${missing.map(k=>PLAN.categories.find(c=>c.key===k).name).join('、')}仍待测/待评。不要用CET分数或想象的水平填空。`};if(d.feedback!=='qualified')return{title:'听读可用，口写分数还需校准',text:'你已录入四科，但口写反馈尚未标记为熟悉雅思标准的评估。暂不据此判断4个月冲8可行性。'};const vals=[d.L,d.R,d.W,d.S];if(d.L>=7.5&&d.R>=7.5&&d.W>=6.5&&d.S>=6.5)return{title:'可以按标准周启动，重点保住输出反馈',text:`当前记录组合约${overall(vals).toFixed(1)}。把8作为挑战目标，用第4/8/12周新题和可靠反馈复核，不视为达分承诺。`};return{title:'先把基础缺口纳入时间预算',text:`当前记录组合约${overall(vals).toFixed(1)}。四个月8+的风险偏高；优先修最低两项，并在第4周讨论是否增加投入或调整考期。`}}
function diagnosticHTML(){const d=state.diagnostic,interpret=diagnosticInterpretation();return`${pageTitle('BASELINE BEFORE PROMISES','先测起点，不把六级换算成雅思。','已知：大三上，四级620、六级568；Academic，每周10–12小时。尚未知道：当前四科、口写反馈与考试模式。',badge('第1周 · 630分钟'))}<div class="two-col"><section class="panel"><h2>诊断流程</h2><div class="numbered" style="margin-top:20px">${[['测听读','各用一套未见官方/正版题，按正式时限完成；不暂停、不查词，记录原始分与来源。'],['留口写样本','写作60分钟；口语一轮11–14分钟，用手机录音。本站不采集声音，也不自动给口写打分。'],['拿四维反馈','请熟悉评分标准的人评Task1/2与完整口语。AI/自评仅作为待校准记录。'],['决定优先级','挑两类最影响分数的错误，安排进下一周。强项保持，弱项获取更多反馈。']].map(([a,b])=>`<div class="step"><div><h3>${a}</h3><p>${b}</p></div></div>`).join('')}</div><div class="hint warning">没有可信口写反馈时，计划可以开始；“四个月一定8”的结论不能开始。首周先做分项诊断；第4、8、12、14、16周安排未见题完整模拟，每次预留约3小时，替换已有练习而不额外加量。</div></section><section class="panel"><h2>保存我的诊断记录</h2><form id="diagnostic-form"><div class="form-row four">${['L','R','W','S'].map((k,i)=>`<label class="field">${PLAN.categories[i].name} Band<select name="${k}">${bandOptions(d[k])}</select></label>`).join('')}</div><div class="form-row"><label class="field">听力原始分 / 40<input type="number" name="Lraw" min="0" max="40" step="1" value="${d.Lraw}"></label><label class="field">Academic阅读原始分 / 40<input type="number" name="Rraw" min="0" max="40" step="1" value="${d.Rraw}"></label></div><label class="field">口语、写作反馈来源<select name="feedback">${[['pending','尚未评估'],['self','自评，仅作练习记录'],['ai','AI反馈，尚需校准'],['qualified','熟悉雅思标准的人评估']].map(([v,t])=>`<option value="${v}" ${d.feedback===v?'selected':''}>${t}</option>`).join('')}</select></label><div class="actions"><button type="submit">保存诊断</button></div></form><p class="inline-note">原始分不自动换成精确Band。官方的35/40≈8是平均参考，具体试卷可能变化。</p><div class="diagnostic-result"><h3>${interpret.title}</h3><p>${interpret.text}</p></div></section></div><div class="section-heading"><h2>下一周，就照这7天做</h2><p>可以交换日期，不能把任务再额外叠加。</p></div><section class="panel">${dailyPlan(1).map((ts,i)=>`<details ${i===0?'open':''}><summary>Day ${i+1} · ${dayLabel(1,i)} · ${ts.reduce((a,t)=>a+t.min,0)}分钟</summary><div class="detail-body">${ts.length?ts.map(dayTaskCard).join(''):'休息日，不安排额外词汇。'}</div></details>`).join('')}</section><div class="section-heading"><h2>诊断结束，要有这5样东西</h2></div><section class="panel"><div class="checklist">${['两套未见L/R的原始分、日期、来源与用时','Task1和Task2原稿，以及四维度改进意见','一轮口语录音和四项反馈','每科最常见的三个问题，区分语言与考试动作','下一周两个优先项，及已排入日程的630分钟'].map((x,i)=>`<label><input type="checkbox" data-diagnostic-check="d${i}" ${state.diagnosticChecks['d'+i]?'checked':''}><span>${x}</span></label>`).join('')}</div></section>`}
function chartHTML(){const records=state.scores.filter(r=>r.type==='new'||r.type==='official').sort((a,b)=>a.date.localeCompare(b.date)).slice(-8);if(records.length<2)return'<div class="empty"><b>等到有两次可比较的新题记录。</b>折线不会用演示数据填满，也不会把重做题混作提分。</div>';const colors=['#1642d8','#70a641','#e7a339','#8857c9'];return `<svg class="score-spark" viewBox="0 0 640 190" role="img" aria-label="最近八次新题或正式考试的四科成绩趋势">${[4,5,6,7,8,9].map(n=>`<line x1="32" x2="628" y1="${166-(n-4)*28}" y2="${166-(n-4)*28}" stroke="#e7ecf4"/><text x="9" y="${170-(n-4)*28}" font-size="11" fill="#73829b">${n}</text>`).join('')}${colors.map((c,i)=>`<polyline fill="none" stroke="${c}" stroke-width="2.5" points="${records.map((r,j)=>`${40+j*(572/(records.length-1))},${166-(Math.max(4,r.bands[i])-4)*28}`).join(' ')}"/>${records.map((r,j)=>`<circle cx="${40+j*(572/(records.length-1))}" cy="${166-(Math.max(4,r.bands[i])-4)*28}" r="4" fill="${c}"/>`).join('')}`).join('')}${records.map((r,j)=>`<text x="${40+j*(572/(records.length-1))}" y="188" text-anchor="middle" font-size="10" fill="#73829b">${r.date.slice(5)}</text>`).join('')}</svg><div class="legend">${['听力','阅读','写作','口语'].map(x=>`<span>${x}</span>`).join('')}</div><p class="inline-note">图表低于4分的点压在底线，精确值见记录表。口写可含自评，请结合反馈来源阅读。</p>`}
function scoresHTML(){return`${pageTitle('SCORE THE EVIDENCE','记录进步，也记录波动。','只比较条件相近的新题。熟题、自评和正式成绩分开标注，不拿最佳一次代替稳定表现。')}<div class="two-col"><section class="panel"><h2>总分计算器</h2><p class="inline-note">官方规则：四科平均分取最近整数或半分；.25向上到半分，.75向上到整数。</p><div class="form-row four">${['听力','阅读','写作','口语'].map((x,i)=>`<label class="field">${x}<select class="calc-band" aria-label="计算器${x}">${bandOptions(state.settings.targets[i],false)}</select></label>`).join('')}</div><div id="calc-result"></div><div class="hint">总分8.0：四科合计至少31，平均7.75。严格高于8：下一个报告分数是8.5，合计至少33，平均8.25。例：8.5/8.5/7/7 → 8.0。</div></section><section class="panel"><h2>新增一次成绩</h2><form id="score-form"><div class="form-row"><label class="field">日期<input name="date" type="date" required value="${today()}"></label><label class="field">练习条件<select name="type"><option value="new">未见题 · 正式时限</option><option value="repeat">重做 / 非限时练习</option><option value="official">正式考试成绩</option></select></label></div><div class="form-row four">${['听力','阅读','写作','口语'].map((x,i)=>`<label class="field">${x}<select name="b${i}" required>${bandOptions('')}</select></label>`).join('')}</div><label class="field">口写评分来源<select name="feedback"><option value="pending">待校准 / 不确定</option><option value="qualified">熟悉雅思标准的人评估 / 正式成绩</option><option value="self">自评</option><option value="ai">AI反馈</option></select></label><label class="field" style="margin-top:14px">试卷来源 + 最关键的一个问题<input name="notes" maxlength="1000" placeholder="例：正版某册Test2；阅读匹配超时，Task2例证不足"></label><button type="submit" style="margin-top:16px">保存成绩记录</button></form></section></div><section class="panel" style="margin-top:22px"><div class="panel-title"><h2>近期趋势</h2>${badge('不含重做题','neutral')}</div>${chartHTML()}</section><section class="panel" style="margin-top:22px"><div class="panel-title"><h2>所有成绩记录</h2>${badge(state.scores.length+'条','neutral')}</div>${state.scores.length?`<div class="table-wrap"><table><thead><tr><th>日期 / 类型</th><th>L</th><th>R</th><th>W</th><th>S</th><th>总分</th><th>口写来源</th><th>证据与问题</th><th>操作</th></tr></thead><tbody>${state.scores.slice().reverse().map(r=>`<tr><td>${r.date}<br><small>${{new:'未见限时',repeat:'重做/非限时',official:'正式考试'}[r.type]}</small></td>${r.bands.map(n=>`<td>${n.toFixed(1)}</td>`).join('')}<td><b>${overall(r.bands).toFixed(1)}</b></td><td>${{qualified:'标准评估',self:'自评',ai:'AI',pending:'待校准'}[r.feedback]}</td><td class="notes">${escapeHTML(r.notes)}</td><td><button class="quiet" data-delete-score="${r.id}">删除</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><b>这里还没有你的成绩。</b>完成诊断后，把真实分数存进来。所有分数均由你录入。</div>'}</section><section class="panel" style="margin-top:22px"><h2>什么时候更接近“准备好了”？</h2><div class="three-col" style="margin-top:18px"><div><span class="eyebrow">01 / 新题</span><h3>听读看三次</h3><p class="inline-note">最近三次不同的未见限时测试，观察中位数和波动，不仅看最高分。</p></div><div><span class="eyebrow">02 / 反馈</span><h3>口写看标准证据</h3><p class="inline-note">至少两次不同题目的可靠反馈接近目标小分；AI/自评分数不能独立作为报名依据。</p></div><div><span class="eyebrow">03 / 稳定</span><h3>完整流程能重复</h3><p class="inline-note">完成连续模拟后仍能控制时间和状态。目标组合留些余量，并满足接收方小分要求。</p></div></div></section>`}
function calcRender(){const els=[...document.querySelectorAll('.calc-band')];if(!els.length)return;const v=els.map(e=>Number(e.value)),avg=v.reduce((a,b)=>a+b,0)/4;$('#calc-result').innerHTML=`<div class="score-result"><strong>${overall(v).toFixed(1)}</strong><div><b>预计报告总分</b><p>合计 ${v.reduce((a,b)=>a+b,0).toFixed(1)} / 平均 ${avg.toFixed(3).replace(/0+$/,'').replace(/\.$/,'')}</p><p>${overall(v)>=state.settings.goal?'这组分数达到你的总分目标。':'距离目标还需 '+Math.max(0,(state.settings.goal-.25)*4-v.reduce((a,b)=>a+b,0)).toFixed(1)+' 个合计分。'} 这只是算术，不是能力评估。</p></div></div>`}
function evidenceHTML(){return`${pageTitle('SOURCES & READING COVERAGE','经验可以借，前提不能省。','两份用户资料20页完整核读，另读8名不同高分考生的经验主文。以下区分官方规则、作者自述和本计划建议。',badge('核读 '+EVIDENCE.reviewed,'neutral'))}<div class="attachment-summary"><div><strong>20 / 20</strong><span>图片页完整核读</span></div><div><strong>10 人</strong><span>不同8–9分考生</span></div><div><strong>0 页</strong><span>尚未读的附件图片</span></div></div><div class="hint warning">所有考生成绩均为自述或帖中展示，未向考试机构核验。成功案例没有对照与失败者分母，不能推出成功概率，也不能证明某课程或App有效。</div><div class="two-col" style="margin-top:22px"><section class="panel"><h2>真正迁移到这份计划的内容</h2><div class="numbered" style="margin-top:19px">${[['先诊断，输出不后置','从第一周纳入写作和口语反馈；不因为CET数值相近就假定雅思基础相同。'],['少刷一套，多修一次','优先证据定位、错因分类、录音重答、反馈重写。保留未见题验证迁移。'],['让10–12小时真实可持续','标准周630分钟、加量周720分钟；忙周360分钟仅应急，不照搬每天4–6小时的经验。']].map(([a,b])=>`<div class="step"><div><h3>${a}</h3><p>${b}</p></div></div>`).join('')}</div></section><section class="panel"><h2>没有照搬的部分</h2><div class="resource"><div><b>“一个月 / 五天 / 十天冲高分”</b><p>日历短不等于投入少，更不等于起点低。海外经历和长期英语使用不能忽略。</p></div></div><div class="resource"><div><b>机械模板、海量单词、所有文章逐句翻译</b><p>根据具体失分选择，不把个人习惯升级为万能公式。</p></div></div><div class="resource"><div><b>固定题数换算表和旧纸笔规则</b><p>原始分以具体卷为准；考试形式与当地可用方式需要在官方预约前确认。</p></div></div><div class="resource"><div><b>AI精确估分 / 课程效果承诺</b><p>AI只做辅助；未体验付费课程，也未验证工具当前价格、免费状态或内容授权。</p></div></div></section></div><div class="section-heading"><h2>官方规则与练习入口</h2><p>官方来源支持考试事实，不为本计划课时背书。</p></div><section class="panel">${EVIDENCE.official.map((s,i)=>`<div class="resource"><span class="resource-no">O${i+1}</span><div><b>${s[0]}</b><p>${s[3]}</p><a class="source-link" href="${escapeHTML(s[2])}" target="_blank" rel="noopener noreferrer">${s[1]}</a></div></div>`).join('')}</section><div class="section-heading"><h2>10名考生：借方法，也看限制</h2><p>前两例来自你给的资料，后八例为补充研究。</p></div>${EVIDENCE.cases.map((c,i)=>`<details ${i<2?'open':''}><summary><span>${String(i+1).padStart(2,'0')} · ${c.name} <span style="font-weight:450;color:var(--muted)">${c.score}</span></span></summary><div class="detail-body"><span class="proof-tag">${c.type}</span><p><b>起点与投入：</b>${c.background}</p><p><b>可以借用：</b>${c.borrow}</p><p><b>不能照搬：</b>${c.limit}</p><a href="${escapeHTML(c.url)}" target="_blank" rel="noopener noreferrer">阅读原始来源</a></div></details>`).join('')}<div class="section-heading"><h2>逐页核读台账</h2><p>压缩包19图 + 原帖补缺封面1图。没有以抽样代替完整阅读。</p></div><section class="panel"><p class="inline-note">A1为柒雅柒雅11页，A2为陆加9页。第一份ZIP缺第1页，已从公开原帖补回封面核读。这里只放内容摘要，不转载原图。</p><div class="ledger">${EVIDENCE.pages.map(p=>`<div class="ledger-row"><div><b>${p[0]}</b><p>${p[1]}</p></div><p>${p[2]}</p>${badge('已完整核读','green')}</div>`).join('')}</div></section><div class="two-col" style="margin-top:22px"><section class="panel"><h2>参考网页实际做了什么</h2><p style="margin-top:12px;font-size:.875rem">MY IELTS包含22个词汇主题、听音/练习模式、词典链接；语法视频/讲义/思维导图；听力179考点词与语料；阅读搜索与同义替换；100句翻译；单词打字准确率、WPM与进度。</p><p class="inline-note">核查时口语标TODO，大小作文标WIP；没有观察到个性化日历、诊断或成绩追踪。本站借鉴分类入口与练习导向，训练计划与交互重新制作，未搬运词库。</p><a href="https://hefengxian.com/my-ielts/#/" target="_blank" rel="noopener noreferrer">打开参考网站</a></section><section class="panel"><h2>核读边界</h2><p style="margin-top:12px;font-size:.875rem">已完整读到外部8例主文结尾；Kirsty的博客与PTT去重。没有读完所有评论和作者全部历史帖，没有体验付费课程，也没有登录个人官方查分账号。</p><p class="inline-note">案例中的资源名称不是购买推荐。每周分配、阶段阈值与四个月日历是基于你时间约束的计划设计，不是经验证的最高效公式。</p></section></div>`}
function settingsHTML(){const s=state.settings,span=dayDiff(s.start,deadline());return`${pageTitle('MAKE THE PLAN FIT YOU','计划可以改，数据记得带走。','Academic、每周10–12小时已确认。默认开始日期为2026年10月8日，规划考试日按四个自然月推算；仍可自行调整。')}<div class="two-col"><section class="panel"><h2>目标与日期</h2><form id="settings-form"><div class="form-row"><label class="field">开始日期<input name="start" type="date" required value="${s.start}"></label><label class="field">总分目标<select name="goal"><option value="8" ${s.goal===8?'selected':''}>至少8.0（主目标）</option><option value="8.5" ${s.goal===8.5?'selected':''}>8.5（严格超过8）</option></select></label></div><div class="form-row"><label class="field">常用周预算<select name="mode">${Object.entries(PLAN.budgets).map(([k,v])=>`<option value="${k}" ${s.mode===k?'selected':''}>${v.label} · ${v.tag}</option>`).join('')}</select></label><label class="field">考试形式意向<select name="examMode"><option value="unknown" ${s.examMode==='unknown'?'selected':''}>待确认当地可用形式</option><option value="computer" ${s.examMode==='computer'?'selected':''}>电脑考试</option><option value="paper" ${s.examMode==='paper'?'selected':''}>写作纸上作答 / 当地待核</option></select></label></div><p class="inline-note">不同城市的可用形式需向官方确认；页面不承诺传统全纸笔仍可预约。考试城市、申请小分要求与截止日仍待你确认。</p><div class="form-row four">${['L 听力','R 阅读','W 写作','S 口语'].map((x,i)=>`<label class="field">${x}目标<select name="t${i}">${bandOptions(s.targets[i],false)}</select></label>`).join('')}</div><p class="inline-note">改总分目标不会悄悄更改四科目标。8.5算术示例：9/9/7.5/7.5。请根据起点和接收方小分要求填写。</p><div class="actions"><button type="submit">保存计划设置</button><button type="button" class="secondary" data-action="target-preset">应用${s.goal===8?'8.0稳妥':'8.5挑战'}目标组合</button></div></form><div class="hint">当前规划：${s.start}—${deadline()}，${span}天；16周核心训练 + ${span-112}个考前机动日。改日期保留按周任务记录；如果是新一轮备考，先备份再重置。</div></section><div class="stack"><section class="panel"><h2>这份网站怎么保存数据？</h2><div class="data-status" style="margin-top:16px">${storageWorks?'本机存储可用':'当前本机存储不可用，请导出备份'}</div><p style="margin-top:15px;font-size:.875rem">进度、成绩、笔记和设置保存在当前浏览器的localStorage。不会自动同步到其他设备，不会上传成绩或录音。清理浏览器数据、隐私模式或换设备可能丢失。</p><div class="actions"><button data-action="export-json">导出JSON备份</button><button class="secondary" data-action="import-json">导入JSON</button></div><p class="inline-note">导入会先验证格式，再请你确认替换当前数据。建议每周导出一次，换设备前也导出。</p></section><section class="panel"><h2>离线与打印</h2><p class="inline-note">下载一份完整静态计划，包含16周课程与来源摘要，可离线阅读或打印保存为PDF；不包含你的个人成绩与笔记。</p><div class="actions"><a class="download-link" href="plan.html" download="IELTS四个月学习计划.html">下载完整计划HTML</a><button class="secondary" data-action="print-plan">打开可打印计划</button></div><p class="inline-note">下载网页不是云同步。继续记录进度请使用本站，迁移进度用JSON。</p></section><section class="panel"><h2>重新开始</h2><p class="inline-note">只清除此网站在当前浏览器中的计划、记录与进度；不会影响其他网站。请先导出备份。</p><button class="danger" style="margin-top:15px" data-action="reset-data">重置本机数据</button></section></div></div>`}
function render(){if(!['today','roadmap','methods','diagnostic','scores','evidence','settings','vocab'].includes(currentPage))currentPage='today';$('#navigation').innerHTML=nav.map(([id,label,path,n])=>`<a href="#${id}" class="${currentPage===id?'active':''}" ${currentPage===id?'aria-current="page"':''} title="${label}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true"><path d="${path}" stroke-linecap="round" stroke-linejoin="round"/></svg><span class="nav-text">${label}</span><span class="nav-number">${n}</span></a>`).join('');$('#top-page').textContent=nav.find(x=>x[0]===currentPage)?.[1]||'计划设置';$('#top-date').textContent=new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'});$('#main').innerHTML=({today:dailyTodayHTML,roadmap:dailyRoadmapHTML,methods:methodsHTML,diagnostic:diagnosticHTML,scores:scoresHTML,evidence:evidenceHTML,settings:settingsHTML,vocab:vocabHTML})[currentPage]();calcRender();bindForms();bindDailyForms()}
function goto(page){if(location.hash==='#'+page){currentPage=page;render()}else location.hash=page}
function completeTask(id,value){if(/^dw/.test(id)){const t=taskById(id);if(!t)throw Error('每日任务不存在。');state.dayChecks[id]=!!value;save();render();return}const match=id.match(/^w(\d+)_/),w=match?Number(match[1]):0;if(!w||w>totalWeeks()||!taskDefs(w).some(x=>x.id===id))throw Error('任务不存在于当前计划。');state.checks[id]=!!value;save();render()}
function exportJSON(){const blob=new Blob([recoveryRaw!==null?recoveryRaw:JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(recoveryRaw!==null?'ielts-recovery-original-':'ielts-progress-')+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('备份已准备下载。请确认浏览器已保存文件。')}
function bindForms(){
 $('#diagnostic-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),d={};['L','R','W','S','Lraw','Rraw'].forEach(k=>d[k]=f.get(k)===''?'':Number(f.get(k)));d.feedback=f.get('feedback');try{state=sanitize({...state,diagnostic:d});const persisted=save();render();if(persisted)toast('诊断已保存。')}catch(err){toast(err.message)}});
 $('#score-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),r={id:'score_'+Date.now(),date:f.get('date'),bands:[0,1,2,3].map(i=>Number(f.get('b'+i))),type:f.get('type'),feedback:f.get('feedback'),notes:f.get('notes')};if([0,1,2,3].some(i=>f.get('b'+i)===''))return toast('请填完四科分数。');try{state=sanitize({...state,scores:[...state.scores,r]});const persisted=save();render();if(persisted)toast('成绩已保存，练习条件也一起保留。')}catch(err){toast(err.message)}});
 $('#settings-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),s={start:f.get('start'),goal:Number(f.get('goal')),mode:f.get('mode'),examMode:f.get('examMode'),targets:[0,1,2,3].map(i=>Number(f.get('t'+i)))};try{state=sanitize({...state,settings:s});selectedWeek=Math.min(selectedWeek,totalWeeks());const persisted=save();render();if(persisted)toast('设置已保存。日期与目标已重新计算。')}catch(err){toast(err.message)}})
}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.go)goto(b.dataset.go);if(b.dataset.mode){state.settings.mode=b.dataset.mode;const persisted=save();render();if(persisted)toast('已切换为'+PLAN.budgets[b.dataset.mode].label+'。各模式的完成记录独立保留。')}if(b.dataset.week){selectedWeek=Number(b.dataset.week);render()}if(b.dataset.method){method=b.dataset.method;render()}if(b.dataset.focus){if(timerEnd){timerLeft=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));timerEnd=null;clearInterval(timerInterval)}focusMinutes=Number(b.dataset.focus);timerLeft=focusMinutes*60;render()}if(b.dataset.deleteScore){const id=b.dataset.deleteScore;askConfirm('删除这条成绩？','这只删除当前浏览器中的这一条记录。已导出的备份不会改变。',()=>{state.scores=state.scores.filter(r=>r.id!==id);const persisted=save();render();if(persisted)toast('成绩记录已删除。')})}const a=b.dataset.action;if(a==='timer-toggle')startStopTimer();if(a==='timer-reset'){timerEnd=null;clearInterval(timerInterval);timerLeft=focusMinutes*60;render()}if(a==='fragment-done'){state.fragments.push({date:today(),minutes:focusMinutes});const persisted=save();render();if(persisted)toast('已记一次碎片练习。若完成了周任务，请再勾选对应项。')}if(a==='save-week-note'){state.notes['w'+selectedWeek]=$('#week-note').value;if(save())toast('这周复盘已保存。')}if(a==='export-json')exportJSON();if(a==='import-json')$('#import-file').click();if(a==='print-plan')window.open('plan.html','_blank','noopener');if(a==='target-preset'){state.settings.targets=state.settings.goal===8?[8.5,8.5,7.5,7.5]:[9,9,7.5,7.5];const persisted=save();render();if(persisted)toast('已应用目标组合，可继续修改。')}if(a==='reset-data')askConfirm('重置本机数据？','任务进度、诊断、成绩、笔记和设置将被清除。此操作无法在网站中撤销；请先导出JSON备份。',()=>{try{localStorage.removeItem(KEY)}catch(e){}recoveryRaw=null;state=makeDefault();selectedWeek=1;selectedDay=0;timerEnd=null;clearInterval(timerInterval);timerLeft=focusMinutes*60;const persisted=save();render();if(persisted)toast('已开始一份空白计划。')})});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.task)completeTask(el.dataset.task,el.checked);if(el.dataset.methodCheck){state.diagnosticChecks['method_'+el.dataset.methodCheck]=el.checked;save()}if(el.dataset.diagnosticCheck){state.diagnosticChecks[el.dataset.diagnosticCheck]=el.checked;save()}if(el.matches('.calc-band'))calcRender()});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>16777216)return toast('文件超过16MB。请选择此网站导出的JSON备份。');try{const incoming=sanitize(JSON.parse(await file.text()));askConfirm('用备份替换当前数据？',`将导入开始日${incoming.settings.start}的计划、${incoming.scores.length}条成绩与任务进度。当前数据会被替换，建议先导出。`,()=>{recoveryRaw=null;state=incoming;selectedWeek=Math.min(selectedWeek,totalWeeks());const persisted=save();render();if(persisted)toast('导入完成，已保存到当前浏览器。')})}catch(err){toast('未导入：'+err.message)}});
window.addEventListener('hashchange',()=>{currentPage=location.hash.slice(1)||'today';if(currentPage==='roadmap')selectedWeek=currentWeek();render();window.scrollTo({top:0,behavior:'instant'})});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{state=sanitize(JSON.parse(e.newValue));render();toast('已同步此浏览器另一标签页的修改。')}catch(err){toast('另一标签页的数据格式有误，未覆盖当前页面。')}}});
selectedWeek=currentWeek();render();if(dateMigrationPending)save();
function registerModelTools(){const context=document.modelContext;if(!context?.registerTool)return;const ac=new AbortController();const register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:ac.signal})).catch(()=>{})}catch(e){}};register({name:'read_ielts_plan',title:'Read IELTS study plan',description:'Read current device-local study settings, selected week tasks and progress. Does not transmit or change data.',inputSchema:{type:'object',properties:{week:{type:'integer',minimum:1,maximum:18}},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).some(k=>k!=='week'))throw Error('Invalid input');const w=input.week??currentWeek();if(!Number.isInteger(w)||w<1||w>totalWeeks())throw Error('Invalid week');return{settings:state.settings,week:w,focus:weekInfo(w),tasks:dailyPlan(w).flat().map(t=>({...t,completed:!!state.dayChecks[t.id]})),legacy_tasks:taskDefs(w).filter(t=>state.checks[t.id]).map(t=>({id:t.id,completed:true}))}}});register({name:'set_ielts_task_completed',title:'Set study task completed',description:'Set a current-plan task completed or not completed, saving in this browser and updating the visible checklist. Use only when the user asks to change progress.',inputSchema:{type:'object',properties:{task_id:{type:'string'},completed:{type:'boolean'}},required:['task_id','completed'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||Object.keys(input).some(k=>!['task_id','completed'].includes(k))||typeof input.task_id!=='string'||typeof input.completed!=='boolean')throw Error('Invalid input');completeTask(input.task_id,input.completed);return{task_id:input.task_id,completed:input.task_id.startsWith('dw')?state.dayChecks[input.task_id]:state.checks[input.task_id],saved_locally:storageWorks}}});window.addEventListener('pagehide',()=>ac.abort(),{once:true})}registerModelTools();
